public object FfiConverterTypeAnimeLib: FfiConverter<AnimeLib, Pointer> {

    override fun lower(value: AnimeLib): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): AnimeLib {
        return AnimeLib(value)
    }

    override fun read(buf: ByteBuffer): AnimeLib {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: AnimeLib) = 8UL

    override fun write(value: AnimeLib, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



